{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.ItemCharge.Get",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.ItemCharge.Get",
    "isEnabled": true,
    "filterTableNo": 5805,
    "description": "Les úthlutun kostnaðarauka á einni kostnaðaraukalínu í innkaupum eða sölu.",
    "selectionDescription": "Sýnir hvernig flutningskostnaði, tolli eða öðrum kostnaðarauka er dreift á vörulínur og hve mikið er enn óúthlutað.",
    "messageDirection": "Outbound",
    "keywords": [
      "kostnaðarauki",
      "úthlutun",
      "óúthlutað",
      "flutningskostnaður",
      "tollur"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "notUsed",
        "description": "The charge line is named under data.documentType, data.documentNo or data.systemId, and data.lineNo; subject is not read."
      },
      "dataRequired": true,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "data.documentNo",
        "form": "document no.",
        "description": "The No. of the open purchase or sales document that holds the charge line. data.documentType says which kind of document it is."
      },
      {
        "source": "data.systemId",
        "form": "guid",
        "description": "The system id of that document, as an alternative to data.documentNo. Send one of them, not both."
      },
      {
        "source": "data.lineNo",
        "form": "integer",
        "description": "The charge line, named by its document and line number."
      }
    ],
    "parameters": [
      {
        "name": "documentType",
        "type": "string",
        "required": true,
        "description": "purchase or sales. Says which kind of document holds the charge line."
      },
      {
        "name": "documentNo",
        "type": "string",
        "required": false,
        "description": "Number of the open purchase or sales document (order, invoice, return order or credit memo). Send this or systemId."
      },
      {
        "name": "systemId",
        "type": "string",
        "required": false,
        "description": "systemId of the document. Send this or documentNo."
      },
      {
        "name": "lineNo",
        "type": "integer",
        "required": true,
        "description": "Line number of the Charge (Item) line."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success on a successful call; Error responses use the standard error envelope."
        },
        {
          "name": "documentType",
          "type": "string",
          "description": "purchase or sales, in lower case."
        },
        {
          "name": "documentNo",
          "type": "string",
          "description": "The No. of the document that holds the charge line."
        },
        {
          "name": "lineNo",
          "type": "integer",
          "description": "The line number of the charge line."
        },
        {
          "name": "itemChargeNo",
          "type": "string",
          "description": "The No. of the item charge on the charge line."
        },
        {
          "name": "quantity",
          "type": "decimal",
          "description": "The quantity of the charge line."
        },
        {
          "name": "qtyToAssign",
          "type": "decimal",
          "description": "The quantity of the charge that is assigned and not yet invoiced."
        },
        {
          "name": "qtyAssigned",
          "type": "decimal",
          "description": "The quantity of the charge that is already invoiced."
        },
        {
          "name": "unassignedQuantity",
          "type": "decimal",
          "description": "The quantity of the charge line minus qtyToAssign and qtyAssigned."
        },
        {
          "name": "assignments",
          "type": "array",
          "description": "The assignment rows of the charge line, in row order.",
          "children": [
            {
              "name": "lineNo",
              "type": "integer",
              "description": "The line number of the assignment row."
            },
            {
              "name": "appliesToDocType",
              "type": "string",
              "description": "What the charge lands on: order, invoice, returnOrder, creditMemo, receipt, transferReceipt, returnShipment, salesShipment, shipment, returnReceipt, quote or blanketOrder."
            },
            {
              "name": "appliesToDocNo",
              "type": "string",
              "description": "The No. of the document the charge lands on."
            },
            {
              "name": "appliesToDocLineNo",
              "type": "integer",
              "description": "The line number on that document."
            },
            {
              "name": "itemNo",
              "type": "string",
              "description": "The item the charge lands on."
            },
            {
              "name": "description",
              "type": "string",
              "description": "The description of the assignment row."
            },
            {
              "name": "qtyToAssign",
              "type": "decimal",
              "description": "The quantity of the charge assigned to that line and not yet invoiced."
            },
            {
              "name": "amountToAssign",
              "type": "decimal",
              "description": "The amount of the charge assigned to that line and not yet invoiced."
            },
            {
              "name": "qtyAssigned",
              "type": "decimal",
              "description": "The quantity of the charge that is already invoiced."
            }
          ]
        }
      ]
    },
    "errors": [
      {
        "code": "MissingParameter",
        "when": "documentType or lineNo is missing, or neither documentNo nor systemId was sent.",
        "fix": "Send documentType, lineNo, and documentNo or systemId."
      },
      {
        "code": "InvalidParameterFormat",
        "when": "A key has the wrong JSON type, or systemId is not a GUID.",
        "fix": "Send documentType, documentNo and systemId as text and lineNo as a whole number."
      },
      {
        "code": "UnknownParameter",
        "when": "The request contains a key this type does not read.",
        "fix": "Remove the unknown key. Allowed keys are documentType, documentNo, systemId and lineNo."
      },
      {
        "code": "InvalidParameter",
        "when": "documentType is not purchase or sales.",
        "fix": "Send purchase or sales."
      },
      {
        "code": "RecordNotFound",
        "when": "No open document or no line matched.",
        "fix": "Check documentNo or systemId, documentType and lineNo."
      },
      {
        "code": "AmbiguousRecord",
        "when": "Several documents of different types have this number.",
        "fix": "Send the systemId of the document instead of documentNo."
      },
      {
        "code": "ConflictingIdentifiers",
        "when": "documentNo and systemId were both sent.",
        "fix": "Send documentNo or systemId, not both."
      },
      {
        "code": "PreconditionFailed",
        "when": "The line is not an item charge line.",
        "fix": "Pass the line no. of a Charge (Item) line."
      },
      {
        "code": "PermissionDenied",
        "when": "The caller cannot read item charge assignments or the document.",
        "fix": "Assign Bifrost Read-Only (extended by Inventory read permissions) and a Business Central permission set that can read these tables."
      },
      {
        "code": "InvalidParameter",
        "when": "The Item Charge domain is turned off for this company.",
        "fix": "Turn the domain on from the Inventory Setup page, then send the call again."
      }
    ],
    "effect": {
      "effect": "read",
      "writes": false,
      "posts": false,
      "changes": "Nothing. The call only reads the assignment rows of one charge line and the quantity that is still unassigned.",
      "idempotent": true,
      "permissionSet": "Bifrost Read-Only"
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.ItemCharge.Assign",
        "useInsteadWhen": "Spread the charge over item lines, or replace the current assignment."
      }
    ],
    "examples": [
      {
        "title": "Read the assignment of a freight charge on a purchase order",
        "request": {
          "type": "Inventory.ItemCharge.Get",
          "data": {
            "documentType": "purchase",
            "documentNo": "106001",
            "lineNo": 30000
          }
        },
        "response": {
          "status": "Success",
          "documentType": "purchase",
          "documentNo": "106001",
          "lineNo": 30000,
          "itemChargeNo": "FREIGHT",
          "quantity": 1,
          "qtyToAssign": 1,
          "qtyAssigned": 0,
          "unassignedQuantity": 0,
          "assignments": [
            {
              "lineNo": 10000,
              "appliesToDocType": "order",
              "appliesToDocNo": "106001",
              "appliesToDocLineNo": 10000,
              "itemNo": "1896-S",
              "description": "ATHENS Desk",
              "qtyToAssign": 0.5,
              "amountToAssign": 50,
              "qtyAssigned": 0
            },
            {
              "lineNo": 20000,
              "appliesToDocType": "order",
              "appliesToDocNo": "106001",
              "appliesToDocLineNo": 20000,
              "itemNo": "1900-S",
              "description": "PARIS Guest Chair, black",
              "qtyToAssign": 0.5,
              "amountToAssign": 50,
              "qtyAssigned": 0
            }
          ]
        }
      }
    ],
    "overview": "Reads how one item charge line on an open purchase or sales document is spread over item lines, the same rows the Item Charge Assignment page shows, and the quantity that is still unassigned.",
    "notes": "Each row in assignments names the line the charge lands on: appliesToDocType (order, invoice, returnOrder, creditMemo, receipt, transferReceipt, returnShipment, salesShipment, shipment or returnReceipt), appliesToDocNo and appliesToDocLineNo, with qtyToAssign, amountToAssign and qtyAssigned (already invoiced). unassignedQuantity is the charge quantity minus qtyToAssign and qtyAssigned. This call changes nothing and does not post the document; use Inventory.ItemCharge.Assign to change the assignment."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nViðbætur (Foundation 28.0.8 eða nýrri) geta kallað á `Argument.SetErrorContext(Parameter, Expected, NextStep)` fyrir aðgerð sem gæti mistekist eftir gagnaskrif og síðan `Argument.ClearErrorContext()` eftir að hún tekst. Gefðu upp heiti færibreytu og þýddan texta, aldrei gildi úr beiðni, skráarinnihald, aðgangsupplýsingar eða kallstafla. Foundation skilar þessu samhengi með upprunalegu `BusinessCentralError` eftir afturköllun, einnig við ómeðhöndlaðar verkefnisvillur; `RespondWithLastError()` notar það líka. Viðmótið grípur ekki villur, staðfestir ekki gagnaskrif og breytir ekki færslumörkum. Haltu `Codeunit.Run` án skilagildis og láttu villur berast áfram þegar `OmitCommit` köll eru keðjuð; bættu aldrei við Boolean `Codeunit.Run` eða `TryFunction` sem skrifar gögn til að endurheimta samhengi. Samhengið er hreinsað milli skilaboða. Kallendur án samhengis halda óbreyttri uppbyggingu svars; þekktar læsingarvillur halda núverandi `Retryable` leiðbeiningum.\r\nSkilaboðagerð sem má aðeins keyra eftir einni leið (Foundation 28.0.9 eða nýrri) les `Argument.GetInvocationSource()`: `Queue` þegar verkraðari keyrir skilaboð sem biðraðarviðmótið setti í röð, `Task` fyrir verkviðmótið (`/tasks`), `Dispatcher` fyrir innra kall í gegnum `Dispatcher ori` (innbyggða MCP-verkfæraþjóninn, hreiðrað kall úr annarri skilaboðagerð) og `Direct` fyrir aðgerðina Keyra vinnslu á síðunni Skilaboð og allt sem ekki er skráð. Aðeins Foundation skráir gildið; gildi í beiðni, færibreytur, uppruni, efni og skrif í færibreytuna breyta því ekki. Hafnaðu öðrum leiðum með `PreconditionFailed` og `nextStep` sem nefnir leiðina sem á að nota.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
